def pm(term):
    return "https://pubmed.ncbi.nlm.nih.gov/?term=" + term.replace(" ", "+").replace("+", "%2B") if False else \
        "https://pubmed.ncbi.nlm.nih.gov/?term=" + term.replace(" ", "+")


def R(*items):
    """items: (label, cite, url) tuples -> numbered refs."""
    return [{"n": str(i + 1), "label": l, "cite": c, "url": u} for i, (l, c, u) in enumerate(items)]


